<script setup lang="ts">import{onMounted,ref}from'vue';import{Bell,CheckCheck,Trash2}from'lucide-vue-next';import EmptyState from'@/components/EmptyState.vue';import{api}from'@/services/api';import type{UserNotification}from'@/types';const items=ref<UserNotification[]>([]);async function load(){items.value=await api.notifications()}async function read(i:UserNotification){if(!i.read)await api.readNotification(i.id);await load()}async function all(){await api.readAllNotifications();await load()}async function remove(id:string){await api.deleteNotification(id);await load()}onMounted(load)</script>
<template><section class="page container narrow"><header class="page-head"><div><p class="eyebrow">NOTIFICATIONS</p><h1>消息中心</h1><p>订单与行程状态会及时通知你</p></div><button class="btn ghost" @click="all"><CheckCheck/>全部已读</button></header><div v-if="items.length" class="notification-list"><article v-for="i in items" :key="i.id" :class="{unread:!i.read}" @click="read(i)"><span class="notify-icon"><Bell/></span><div><h3>{{i.title}}</h3><p>{{i.content}}</p><small>{{i.createdAt.replace('T',' ').slice(0,16)}}</small></div><button class="icon-btn danger" @click.stop="remove(i.id)"><Trash2/></button></article></div><EmptyState v-else title="暂无消息" hint="新的订单状态会显示在这里"/></section></template>
